      }
    });
  });

  describe('MCP 工具调用 — 业务成功路径（带 project_root）', () => {
    afterEach(() => {
      setResolvedRoot(process.cwd());
    });

    it('config_get 返回 key、value 和 exists 字段', async () => {
      const { dir, cleanup } = setupTempProject({ schema: 'spec-driven' });
      setResolvedRoot(dir);
      try {
        const result = await client.callTool({
          name: 'config_get',
